    h, w = len(grid), len(grid[0])
    color = 2
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    marker = next(grid[r][c] for r in range(h) for c in range(w)
                  if grid[r][c] not in (0, color))
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    out = [row[:] for row in grid]

    # Project the rectangle along rows and columns. A marker on a line
    # determines the direction in which that line is extended.
    for r in range(r0, r1 + 1):
        cs = [c for mr, c in marks if mr == r]
        if cs:
            end = min(cs)
            start = max(cs)
            if end < c0:
                for c in range(c0, w):
                    if out[r][c] == 0:
                        out[r][c] = color
            elif start > c1:
                for c in range(0, c1 + 1):
                    if out[r][c] == 0:
                        out[r][c] = color
        else:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = color

    for c in range(c0, c1 + 1):
        rs = [r for r, mc in marks if mc == c]
        if rs:
            if max(rs) < r0:
                for r in range(r0, h):
                    if out[r][c] == 0:
                        out[r][c] = color
            elif min(rs) > r1:
                for r in range(r1 + 1):
                    if out[r][c] == 0:
                        out[r][c] = color
        else:
            for r in range(h):
                if out[r][c] == 0:
                    out[r][c] = color
    return out
